using System.IO;
using FluentAssertions;
using Moq;
using NUnit.Framework;
using NzbDrone.Core.MediaFiles.RecoverableOperations;
using NzbDrone.Core.Test.Framework;
namespace NzbDrone.Core.Test.MediaFiles.RecoverableOperations { [TestFixture] public class RecoverableOperationRecoveryServiceFixture : DbTest<RecoverableOperationRepository, RecoverableOperation> { [Test] public void corrupt_low_state_should_not_starve_later_recoverable_rows() { var corrupt = Subject.CreatePending(RecoverableOperationRepositoryFixture.Request("corrupt", "movie:corrupt")); corrupt.State = (RecoverableOperationState)999; Storage.Update(corrupt); var later = Subject.CreatePending(RecoverableOperationRepositoryFixture.Request("after-corrupt", "movie:after-corrupt")); var service = new RecoverableOperationRecoveryService(Subject); service.Classify(1).Should().Equal(later.Id); Subject.GetById(corrupt.Id).State.Should().Be((RecoverableOperationState)999); Subject.GetById(later.Id).State.Should().Be(RecoverableOperationState.RecoveryRequired); } [Test] public void failing_first_handler_should_not_block_later_rows_in_the_same_page() { var first = Subject.CreatePending(RecoverableOperationRepositoryFixture.Request("first-failure", "movie:first-failure", operationType: RecoverableOperationType.Delete)); var second = Subject.CreatePending(RecoverableOperationRepositoryFixture.Request("second-progress", "movie:second-progress", operationType: RecoverableOperationType.Delete)); var handler = new Mock<IRecoverableMovieFileDeletionRecoveryHandler>(); handler.Setup(x => x.Recover(It.IsAny<RecoverableOperation>())).Callback<RecoverableOperation>(operation => { if (operation.Id == first.Id) throw new IOException("persistent recovery failure"); Subject.MarkRecoveryRequired(operation.Id, operation.State, operation.Version, "processed later row"); }); var service = new RecoverableOperationRecoveryService(Subject, handler.Object); service.Classify(2).Should().Equal(first.Id, second.Id); Subject.GetById(first.Id).State.Should().Be(RecoverableOperationState.RecoveryRequired); Subject.GetById(second.Id).State.Should().Be(RecoverableOperationState.RecoveryRequired); } [Test] public void repeated_bounded_runs_advance_past_low_unsupported() { var low = Subject.CreatePending(RecoverableOperationRepositoryFixture.Request("low", "movie:10")); var later = Subject.CreatePending(RecoverableOperationRepositoryFixture.Request("later", "movie:11")); var service = new RecoverableOperationRecoveryService(Subject); service.Classify(1).Should().Equal(low.Id); Subject.GetById(low.Id).State.Should().Be(RecoverableOperationState.RecoveryRequired); service.Classify(1).Should().Equal(later.Id); Subject.GetById(later.Id).State.Should().Be(RecoverableOperationState.RecoveryRequired); } } }
